editorialMd:
Build middleValues

Find the middle node of the linked list given by `head`. Each node stores a number in val and a link in next. Use two pointers: one moves one link at a time, and the other moves two. If there are two middle nodes, choose the second one. Record the values from that middle node to the end. An empty list gives an empty `middleValues`.

Return the answer

Add only the numbers in `middleValues` that are greater than 0. Store the sum in `positiveTotal`. Complete `midpointChainPositiveInkInvoice` so it returns `positiveTotal`. Return it, do not print it.

Why this works

Each value in `middleValues` follows task 1. The later tasks use only those values. Keeping these steps separate helps avoid returning the list when the question asks for one number. Check empty input, one item, repeated values, and the largest allowed input.

Efficiency goal: time O(n); extra memory, including the helper list, O(n). n is the number of nodes. These labels describe how work and memory grow with the input.

javascript
function midpointChainPositiveInkInvoice(head) {
  const a=head; let out=[];
  let slow=a,fast=a;while(fast&&fast.next){slow=slow.next;fast=fast.next.next;}for(let node=slow;node;node=node.next)out.push(node.val);
  return out.reduce((s,x)=>s+Math.max(0,x),0);
}


typescript
type ListNode = { val: number; next: ListNode | null };
function midpointChainPositiveInkInvoice(head: ListNode | null): number {
  const a=head; let out:number[]=[];
  let slow=a,fast=a;while(fast&&fast.next){slow=slow!.next;fast=fast.next.next;}for(let node=slow;node;node=node.next)out.push(node.val);
  return out.reduce((s,x)=>s+Math.max(0,x),0);
}


python
def midpointChainPositiveInkInvoice(head):
    a=head
    out=[]
    slow=fast=a
    while fast and fast.next:
        slow=slow.next
        fast=fast.next.next
    node=slow
    while node:
        out.append(node.val)
        node=node.next
    return sum(x for x in out if x>0)


java
class Solution {
  public int midpointChainPositiveInkInvoice(ListNode head) {
    ListNode a=head; List<Integer> out=new ArrayList<>();
    {ListNode slow=a,fast=a;while(fast!=null&&fast.next!=null){slow=slow.next;fast=fast.next.next;}for(ListNode node=slow;node!=null;node=node.next)out.add(node.val);}
    int answer=0;for(int x:out)if(x>0)answer+=x;return answer;
  }
}
